"""Applies the iOS settings Smriti Sathi needs to a project generated by
`flutter create --platforms ios`. Fails loudly if the template changed.

  patch_ios.py project [dir]   Info.plist and AppDelegate (run after flutter create)
  patch_ios.py podfile [dir]   Podfile (run after `flutter build ios --config-only`,
                               which is what creates the Podfile)
"""
import plistlib
import sys
from pathlib import Path

stage = sys.argv[1] if len(sys.argv) > 1 else ""
root = Path(sys.argv[2] if len(sys.argv) > 2 else ".") / "ios"


def fail(msg: str) -> None:
    sys.exit(f"patch failed: {msg}")


def patch(path: Path, old: str, new: str) -> None:
    text = path.read_text()
    if old not in text:
        fail(f"{old!r} not found in {path}")
    path.write_text(text.replace(old, new, 1))


def project() -> None:
    plist = root / "Runner" / "Info.plist"
    with plist.open("rb") as f:
        data = plistlib.load(f)
    data["CFBundleDisplayName"] = "Smriti Sathi"
    data["NSCameraUsageDescription"] = (
        "Smriti Sathi uses the camera only when you choose to take a photo for a "
        "profile or a family member.")
    data["NSPhotoLibraryUsageDescription"] = (
        "Smriti Sathi uses your photos only when you choose one for a profile or a "
        "family member.")
    data["NSLocationWhenInUseUsageDescription"] = (
        "So your family can find you in an emergency. Location is not collected yet.")
    # url_launcher needs to know it may open the dialer.
    data["LSApplicationQueriesSchemes"] = ["tel"]
    with plist.open("wb") as f:
        plistlib.dump(data, f)

    # flutter_local_notifications: show reminders while the app is open.
    patch(
        root / "Runner" / "AppDelegate.swift",
        "    GeneratedPluginRegistrant.register(with: self)\n",
        "    if #available(iOS 10.0, *) {\n"
        "      UNUserNotificationCenter.current().delegate = self as UNUserNotificationCenterDelegate\n"
        "    }\n"
        "    GeneratedPluginRegistrant.register(with: self)\n",
    )
    print("iOS project patched")


# permission_handler only compiles in the permissions an app asks for.
MACROS = ["PERMISSION_CAMERA=1", "PERMISSION_PHOTOS=1", "PERMISSION_LOCATION=1",
          "PERMISSION_NOTIFICATIONS=1"]


def podfile() -> None:
    pod = root / "Podfile"
    if not pod.exists():
        fail(f"{pod} does not exist (run `flutter build ios --config-only` first)")
    text = pod.read_text()
    if "platform :ios" in text and "# platform :ios" in text:
        text = text.replace("# platform :ios, '13.0'", "platform :ios, '13.0'", 1)
    elif "platform :ios" not in text:
        fail("no platform line in Podfile")
    pod.write_text(text)
    if "PERMISSION_CAMERA" in pod.read_text():
        print("Podfile already patched")
        return
    defs = ", ".join(f"'{m}'" for m in MACROS)
    patch(
        pod,
        "    flutter_additional_ios_build_settings(target)\n",
        "    flutter_additional_ios_build_settings(target)\n"
        "    target.build_configurations.each do |config|\n"
        "      config.build_settings['GCC_PREPROCESSOR_DEFINITIONS'] ||= ['$(inherited)']\n"
        f"      config.build_settings['GCC_PREPROCESSOR_DEFINITIONS'].concat([{defs}])\n"
        "    end\n",
    )
    print("Podfile patched")


if stage == "project":
    project()
elif stage == "podfile":
    podfile()
else:
    sys.exit(__doc__)
